import{_ as n,l as i,o as e,c as l,v as o,p as s,x as t,d as h,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"多对一匹配","description":"","frontmatter":{"title":"多对一匹配","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/many-to-one-matching.md","filePath":"econ/many-to-one-matching.md","lastUpdated":1789023840000}'),d={name:"econ/many-to-one-matching.md"};function A(c,a,m,B,D,_){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="多对一匹配" tabindex="-1">多对一匹配 <a class="header-anchor" href="#多对一匹配" aria-label="Permalink to &quot;多对一匹配&quot;">​</a></h1><div class="epigraph"><p>医院有名额、医生一人一岗时，稳定仍可定义，延迟接受仍给出稳定匹配；但录取问题与把每个名额当成独立「人」的婚姻问题并不等价。</p><footer>—— Roth, The College Admissions Problem Is Not Equivalent to the Marriage Problem, Journal of Economic Theory, 1985；The Evolution of the Labor Market for Medical Interns and Residents, Journal of Political Economy, 1984</footer></div><p><a href="/econ/matching-strategy-proof">上一课</a>在一对一上钉了：延迟接受对求婚方策略证明，对接收方可操纵，稳定与双边策略证明不可兼得。缺口是名额：医院招多人、学院有配额。是否把每个床位复制成独立代理人，一对一定理原样搬？Roth 说不能。本课钉多对一的稳定、响应性偏好与农村医院定理，不把学校优先权当成学院自己的福利——那是下一课学校选择。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>医生集合 \\(D\\)，医院集合 \\(H\\)，医院 \\(h\\) 有整数名额 \\(q_h\\)。匹配使每位医生至多一家，医院 \\(h\\) 至多 \\(q_h\\) 人。阻塞：一名医生与一家医院互相宁可「改配」——对医院而言，宁可在现有集合里换人或用空额加人。稳定：无阻塞对、无阻塞个人（宁可空缺）。</p><p>若医院对医生集合的偏好是<strong>响应性的</strong>（responsive）：对单人的排序能一致地扩展到集合（更好的人替换更差的人，集合变好；空额当最差），则 Gale–Shapley 的延迟接受仍终止于稳定匹配。医生求婚 DA 给出医生最优稳定匹配。</p><h3 id="复制名额不是同一博弈" tabindex="-1">复制名额不是同一博弈 <a class="header-anchor" href="#复制名额不是同一博弈" aria-label="Permalink to &quot;复制名额不是同一博弈&quot;">​</a></h3><p>把医院 \\(h\\) 拆成 \\(q_h\\) 个「单位」，每个单位当一对一的人，偏好抄医院对单人的排序——稳定匹配的集合可以对应，<strong>策略</strong>不对应。医院是一个玩家，谎报的是一份名单或名额，不是 \\(q_h\\) 个独立单位分别操纵。Roth 1985：学院录取在策略上不等于婚姻市场。一对一上「接收方可操纵」在多对一里更宽：还可以隐瞒名额、改集合偏好。</p><p><span class="marginnote">农村医院定理（Roth, 1986）：所有稳定匹配中，同一医院的填满人数相同；若某医院在一个稳定匹配中未满，则它在所有稳定匹配中得到同一集合。名额空在农村的，稳定解救不了——那是供给，不是算法选边。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：有限、严格单人排序、响应性、配额固定。算法：医生求婚或医院求婚的 DA，暂持改为「暂持当前最好的至多 \\(q_h\\) 人」。先证稳定，再证农村医院（名额与未匹配集合在稳定集上不变）。最后给反例：非响应性（要「成对互补」的科室组合）时，稳定可以空，或 DA 的暂持规则没有意义。</p>',11)),(e(),s(p,null,{default:t(()=>[E(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OT%5B%22%E4%B8%80%E5%AF%B9%E4%B8%80%20DA%22%5D%20--%3E%20Q%5B%22%E5%8C%BB%E9%99%A2%E5%90%8D%E9%A2%9D%20q%22%5D%0A%20%20Q%20--%3E%20RESP%5B%22%E5%93%8D%E5%BA%94%E6%80%A7%EF%BC%9A%E9%9B%86%E5%90%88%E5%81%8F%E5%A5%BD%E8%B7%9F%E5%8D%95%E4%BA%BA%E8%B5%B0%22%5D%0A%20%20RESP%20--%3E%20STAB%5B%22DA%20%E4%BB%8D%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20COPY%5B%22%E6%8B%86%E6%88%90%20q%20%E4%B8%AA%E5%8D%95%E4%BD%8D%22%5D%20--%3E%20NEQ%5B%22%E7%AD%96%E7%95%A5%E4%B8%8D%E7%AD%89%E4%BB%B7%22%5D%0A%20%20RH%5B%22%E5%86%9C%E6%9D%91%E5%8C%BB%E9%99%A2%22%5D%20--%3E%20SAME%5B%22%E7%A8%B3%E5%AE%9A%E9%9B%86%E4%B8%8A%E5%90%8D%E9%A2%9D%E7%9B%B8%E5%90%8C%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>医院求婚 DA 给出医院最优稳定匹配，医生更差。配额没有把双边策略证明变可能。</p><p>NRMP 历史：医院求婚改成医生求婚，是选哪一边被策略保护，不是「有没有稳定」。名额 \\(q_h\\) 本身若可被医院隐瞒（少报床位），稳定与策略证明都要另查：少报可以改变谁被暂持，从而在格上挪位置。一对一没有这条杠杆。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>响应性让「医院当作对单人排序的扩」与「对集合排序」一致，于是阻塞对仍能用单人语言写。DA 的暂持就是在名额内维持当前最优集合。农村医院说：稳定格改变的是「谁和谁配」，不是「农村一共几个岗被填」。操纵改质量，不改那些岗的空置——若空置是偏好与地理，不是边选错。</p><p>与一对一策略证明的衔接：医生求婚 DA 对医生仍策略证明（在响应性、无捆绑下）。医院一边：名额与集合使谎报空间更大，不是简单「接收方在格的坏端」。夫妻捆绑、互补会破坏存在性与策略证明，本课只钉经典住院医师。</p><h3 id="稳定仍对立两边" tabindex="-1">稳定仍对立两边 <a class="header-anchor" href="#稳定仍对立两边" aria-label="Permalink to &quot;稳定仍对立两边&quot;">​</a></h3><p>医生最优稳定匹配对医院仍是稳定集里较差的一端（在响应性下有格）。选求婚边仍是选谁被保护。多对一只是把「一端」从单人改成带配额的机构，没有把双边策略证明变可能。</p><p><span class="marginnote">Roth 1984 追溯美国住院医师市场：早期爆炸要约与逐级退出，稳定匹配作为集中清算恢复了市场。算法细节后来改求婚边，动机正是本课与上一课的激励，不是运算速度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>工资可谈的赋值博弈、合同匹配（Hatfield–Milgrom）把货币请回来，替代性条件替换响应性。那是后继。不要把医院名额写成限价簿的深度。互补偏好下稳定可空，本课不靠它说话。</p><p>夫妻捆绑把两名医生的偏好焊在一起，稳定可以空，DA 的求婚方策略证明也会坏——这是配额之外的另一条裂口，住院医师匹配后来用补丁处理，不是本课的响应性定理能覆盖。学校选择里学校往往根本没有这类福利互补，优先权是另一套对象。</p><p>后课默认：多对一在响应性下 DA 稳定，复制单位不等于同一策略博弈；农村医院钉住空置。下一课学校选择：机构一边往往只有优先权，没有福利。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>配额加响应性，DA 仍给出稳定匹配。</li><li>录取问题在策略上不等于把名额拆成婚姻市场。</li><li>农村医院：稳定解不改变未满医院的名额与集合。</li><li>医生求婚保护医生诚实；医院仍可操纵。</li><li>出处：Roth, <em>JPE</em>, 1984；<em>JET</em>, 1985；农村医院 <em>AER</em>, 1986。</li></ul>',14))])}const q=n(d,[["render",A]]);export{f as __pageData,q as default};
